398		st := e.RiskStatus()
399		if st.Restricted || st.Day != 2 || st.Baseline != 910 || st.Equity != 910 {
400			t.Fatalf("跨日应重定基准并清除限制: %+v", st)
401		}
402		if o, _ := e.Order(pending); o.Status != StatusCanceled {
403			t.Fatal("跨日不得恢复旧订单")
404		}
405		if err := e.Cancel(pending); err == nil {
406			t.Fatal("旧订单仍处撤销态，重复撤销必须报错")
407		}
408		// 跨日不产生风险记录，旧触线记录保持日号 1。
409		if len(e.Records()) != day1Records {
410			t.Fatal("跨日本身不得新增事件记录")
411		}
412		rec := lastRiskRecord(t, e)
413		if rec.RiskDay != 1 {
414			t.Fatalf("跨日不得改写旧触线记录: %+v", rec)
415		}
416	
417		// 新日可正常交易，且可再次触线（新日一条新触线记录）。
418		mustBuy(t, e, "A", 1, 1)
419		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 1}, 1) // 净值不变
420		if countRiskRecords(e) != 1 {
421			t.Fatal("新日尚未再次触线")
422		}
