		Symbol:     symbol,
		Side:       Buy,
		Qty:        qty,
		Limit:      limit,
		Reason:     reason,
		AmtEnabled: true,
		AmtLimit:   e.amtLimit,
	}
	if t != nil {
		r.AmtHolding = t.holding
		r.AmtBuyReserved = t.reserved
		r.AmtTotal = t.total
		if withApply {
			r.AmtApplyTotal = applyTotal
		}
		r.AmtQuoteRefs = append([]RiskQuoteRef(nil), t.refs...)
	}
	e.appendRecord(r, e.symbols[symbol])
}

