func TestAmountOverflowOnSetKeepsOldSetting(t *testing.T) {
	e, _ := NewEngine(1_000_000)
	mustSetMax(t, e, "A", 10)
	big := int64(math.MaxInt64 / 2)
	mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: big}, 1)
	id := mustBuy(t, e, "A", 3, big) // 3 × big 溢出
	_ = id

	// 当前合计已溢出：任何设置都整体报错，只增加一条拒绝记录。
	before := len(e.Records())
	_, err := e.SetPositionAmountLimit(math.MaxInt64)
	if !errors.Is(err, ErrInt64Overflow) {
		t.Fatalf("设置时金额溢出必须返回 ErrInt64Overflow，实际 %v", err)
	}
	if st := e.PositionAmountStatus(); st.Enabled {
		t.Fatal("溢出后设置不得生效")
	}
	if len(e.Records()) != before+1 {
		t.Fatal("溢出设置只能增加一条拒绝记录")
	}
	if r := e.Records()[before]; r.Kind != RecordRejected {
		t.Fatalf("应为拒绝记录: %+v", r)
	}

	// 先设置一个合法上限（买单占用 3×big 未溢出：3×(MaxInt64/2) < MaxInt64）。
	e2, _ := NewEngine(1_000_000)
	mustSetMax(t, e2, "A", 10)
	mustQuote(t, e2, "A", Quote{Seq: 1, Moment: 1, Price: big}, 1)
	mustBuy(t, e2, "A", 2, big)
	if _, err := e2.SetPositionAmountLimit(math.MaxInt64); err != nil {
		t.Fatalf("首次设置在未溢出时应成功: %v", err)
	}
	// 再提交使合计溢出的买单：下单整体报错并留一条拒绝，设置保持不变。
	before = len(e2.Records())
	if _, err := e2.Buy("A", 2, big); !errors.Is(err, ErrInt64Overflow) {
		t.Fatalf("申请后合计溢出必须返回 ErrInt64Overflow，实际 %v", err)
	}
	if len(e2.Records()) != before+1 {
		t.Fatal("溢出下单只能增加一条拒绝记录")
	}
	if st := e2.PositionAmountStatus(); !st.Enabled || st.Limit != math.MaxInt64 {
		t.Fatalf("溢出下单不得改写上限: %+v", st)
	}
}

